package stock

import "fmt"

// Level tracks the on-hand quantity for one SKU.
type Level struct {
	sku    string
	onHand int
}

// NewLevel returns a Level for sku with the given on-hand quantity.
func NewLevel(sku string, onHand int) *Level {
	return &Level{sku: sku, onHand: onHand}
}

// OnHand returns the quantity currently on hand.
func (l *Level) OnHand() int {
	return l.onHand
}

// Receive adds delivered units.
func (l *Level) Receive(units int) {
	l.onHand += units
}

func legacyRestock(l *Level, units int) {
	if units > 0 {
		l.onHand = l.onHand + units
	}
}

func (l *Level) describe() string {
	return fmt.Sprintf("%s: %d on hand", l.sku, l.onHand)
}
